const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), W=960,H=600;let state='title',scene='house',last=0,elapsed=0,toastTimer=0,dialogue=null,dialogueIndex=0,attackFlash=0,player={x:480,y:390,face:1,hp:3,inv:0},keys={},clues=new Set(),visited={},flags={talked:false,choice:false},enemy={x:625,y:350,hp:3,active:true,hit:0};
const chapters={house:['CAPÍTULO I · A CASA','Encontra três coisas que te pertencem.'],city:['CAPÍTULO II · A CIDADE','Procura a estação. A rapariga sabe o teu nome.'],station:['CAPÍTULO III · A ESTAÇÃO','Enfrenta o que ficou para trás.']};
const items={house:[{id:'photo',x:476,y:362,label:'Fotografia',mark:'▧'},{id:'tape',x:306,y:285,label:'Cassete',mark:'▰'},{id:'letter',x:657,y:284,label:'Carta dobrada',mark:'✉'}],city:[{id:'memory',x:232,y:245,label:'Gravação',mark:'♫'}],station:[]};
const dialogues={photo:[['TU','Cinco pessoas. Eu... e quatro desconhecidos.'],['TU','Conheço estes rostos. Tenho a certeza. Não me lembro de nenhum nome.'],['NOTA NO VERSO','“Se estás a ler isto, não confies nas tuas memórias.”']],tape:[['GRAVAÇÃO · 03:17','Se encontraste a fita, então falhei. Não deixes a Inês levar-te à estação. Ela sabe o que fizemos.'],['TU','A minha voz. Mas eu nunca disse isto.']],letter:[['CARTA','Inês — não foi um acidente. Fui eu que tranquei a porta. Lembra-te disso quando ele acordar.'],['TU','“Ele”. Quem é ele?']],ines:[['INÊS','Sabia que voltavas.'],['TU','Conheces-me?'],['INÊS','Conhecia. A cidade toda sabe o que aconteceu naquela noite. Só tu é que te esqueceste.'],['TU','A fita diz para não confiar em ti.'],['INÊS','A fita mente. Ou talvez diga a verdade. As duas coisas podem ser iguais. A estação fica a norte.']],memory:[['VOZ NA GRAVAÇÃO','Quatro amigos. Uma porta trancada. Uma noite em que ninguém quis ser o primeiro a pedir ajuda.'],['TU','Lembro-me. Eu tinha a chave. Ouvi-os chamar.'],['TU','Se sair daqui, tenho de levar esta verdade comigo.']],final:[['INÊS','Então? Lembraste-te?'],['TU','Lembro-me de ter escolhido o silêncio. Não sei se isso é perdão.'],['INÊS','Não é. Mas é um começo.']]};
function startGame(){state='play';$('#title').classList.add('hide');$('#hud').style.display='block';$('#mobile').style.display='';scene='house';player={x:480,y:390,face:1,hp:3,inv:0};clues.clear();flags={talked:false,choice:false};enemy={x:625,y:350,hp:3,active:true,hit:0};updateHud();say('photo',false);}
function updateHud(){const c=chapters[scene];$('#chapter').textContent=c[0];$('#objective').textContent=c[1];$('#clues').firstChild.textContent=`FRAGMENTOS　${clues.size} / 4`;$('#health').innerHTML='';for(let i=0;i<3;i++){let d=document.createElement('i');d.className='heart'+(i>=player.hp?' off':'');$('#health').append(d)}$('#clock').textContent='03:'+String(17+Math.floor(elapsed/12)%43).padStart(2,'0')}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=2.3}
function say(key,advance=true){dialogue=dialogues[key];dialogueIndex=0;if(!dialogue)return;showLine();$('#dialogue').classList.add('open');keys={};}
function showLine(){let l=dialogue[dialogueIndex];$('#speaker').textContent=l[0];$('#line').textContent=l[1]}
function nextLine(){if(!dialogue)return;if(++dialogueIndex>=dialogue.length){$('#dialogue').classList.remove('open');let old=dialogue;dialogue=null;if(old===dialogues.ines){flags.talked=true;updateHud()}if(old===dialogues.memory){clues.add('memory');updateHud();toast('Fragmento recuperado · A noite do incêndio')}if(old===dialogues.final){finish()}return}showLine()}
function finish(){state='ending';$('#hud').style.display='none';$('#mobile').style.display='none';$('#ending').classList.remove('hide');$('#endingText').textContent=clues.has('memory')?'Agora lembras-te dos quatro nomes. O teu também. A verdade não te absolve — mas, pela primeira vez, já não estás sozinho com ela.':'A cidade ficou para trás, mas as memórias seguiram contigo. Talvez um dia consigas abrir a última porta.'}
$('#begin').onclick=startGame;$('#again').onclick=()=>{$('#ending').classList.add('hide');$('#title').classList.remove('hide');state='title'};
function interact(){if(dialogue){nextLine();return}let nearest=null,dist=72;for(const item of items[scene]||[]){if(clues.has(item.id))continue;let d=Math.hypot(player.x-item.x,player.y-item.y);if(d<dist){dist=d;nearest=item}}
if(nearest){if(nearest.id==='photo'||nearest.id==='tape'||nearest.id==='letter'){clues.add(nearest.id);say(nearest.id);toast('Objeto encontrado');if(clues.size===3){chapters.house[1]='Sai pela porta da frente.'}}else say('memory');updateHud();return}
if(scene==='house'&&player.y<165&&Math.abs(player.x-480)<85){if(clues.size<3){toast('Ainda há coisas que precisas de encontrar.');return}scene='city';player.x=480;player.y=520;updateHud();toast('Vila de Santa Bruma · 03:17');return}
if(scene==='city'){if(Math.hypot(player.x-690,player.y-260)<100){if(!flags.talked){say('ines');return}if(clues.has('memory')){scene='station';player.x=480;player.y=520;updateHud();toast('Estação de Santa Bruma');return}toast('A entrada da estação está a norte.');}else toast('A rua está vazia. A névoa esconde o resto.');return}
if(scene==='station'&&Math.hypot(player.x-480,player.y-150)<110){if(!clues.has('memory'))say('memory');else say('final');return}
toast('Nada aqui responde.');}
function attack(){if(state!=='play'||dialogue)return;attackFlash=.28;if(scene==='city'&&enemy.active&&Math.hypot(player.x-enemy.x,player.y-enemy.y)<112){enemy.hp--;enemy.hit=.3;enemy.x+=Math.sign(enemy.x-player.x)*30;toast(enemy.hp<=0?'A sombra dissolve-se na luz.':'A luz fere a sombra.');if(enemy.hp<=0){enemy.active=false;clues.add('shadow');updateHud()}}}
function setKey(k,on){keys[k]=on}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(dialogue&&(k==='e'||k==='enter'||k===' ')){nextLine();return}if(k==='e'||k==='enter'){interact();return}if(k===' '){attack();return}if(k==='shift')setKey('run',true);if(k==='w'||k==='arrowup')setKey('up',true);if(k==='s'||k==='arrowdown')setKey('down',true);if(k==='a'||k==='arrowleft')setKey('left',true);if(k==='d'||k==='arrowright')setKey('right',true)});
window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='shift')setKey('run',false);if(k==='w'||k==='arrowup')setKey('up',false);if(k==='s'||k==='arrowdown')setKey('down',false);if(k==='a'||k==='arrowleft')setKey('left',false);if(k==='d'||k==='arrowright')setKey('right',false)});
document.querySelectorAll('.mobile-controls button').forEach(b=>{let k=b.dataset.key;if(k==='interact'){b.addEventListener('pointerdown',e=>{e.preventDefault();interact()});return}if(k==='attack'){b.addEventListener('pointerdown',e=>{e.preventDefault();attack()});return}if(k==='wait')return;b.addEventListener('pointerdown',e=>{e.preventDefault();setKey(k,true)});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>setKey(k,false)))});
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function move(dt){if(state!=='play'||dialogue)return;let dx=(keys.right?1:0)-(keys.left?1:0),dy=(keys.down?1:0)-(keys.up?1:0),len=Math.hypot(dx,dy)||1;if(dx)player.face=Math.sign(dx);let speed=keys.run?220:145;let nx=player.x+dx/len*speed*dt,ny=player.y+dy/len*speed*dt;player.x=clamp(nx,36,924);player.y=clamp(ny,72,566);
// Architectural collision zones
if(scene==='house'){if(player.y<170&&Math.abs(player.x-480)>62)player.y=170;if(player.y>465&&player.x>305&&player.x<650)player.y=465;}
if(scene==='city'){if(player.x<190&&player.y>180&&player.y<440)player.x=190;if(player.x>775&&player.y<480)player.x=775;}
if(scene==='station'){if(player.y<120&&Math.abs(player.x-480)>115)player.y=120;}
if(player.inv>0)player.inv-=dt;if(attackFlash>0)attackFlash-=dt;
if(scene==='city'&&enemy.active){let d=Math.hypot(player.x-enemy.x,player.y-enemy.y);if(d>35){enemy.x+=(player.x-enemy.x)/d*48*dt;enemy.y+=(player.y-enemy.y)/d*48*dt}if(d<34&&player.inv<=0){player.hp--;player.inv=1.3;toast('A sombra rasga a tua memória.');updateHud();if(player.hp<=0){player.hp=3;player.x=480;player.y=520;toast('A luz da fotografia devolve-te ao início da rua.')}}}}

